def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    slots = int(supply / WATER_REQ)
    if slots < 0:
        slots = 0

    prev_bids = []
    extreme_count = 0
    needy_count = 0
    rich_aggressive = 0

    for oid, opp in alive:
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
            needy_count += 1
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 120:
                extreme_count += 1
        if opp.get('budget', 0) >= 300:
            if bid is not None and bid >= 100:
                rich_aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = False
    if hp <= 2 or no_water_days >= 2:
        danger = True
    elif hp <= 4 and no_water_days >= 1:
        danger = True

    if danger:
        target = max(95.0, highest_prev + 6.0)
        return float(min(budget, target))

    if slots >= 2:
        base = 16.0
        if extreme_count >= 2:
            base = 9.0
        elif highest_prev >= 100:
            base = 12.0
        if no_water_days == 1:
            base += 10.0
        if hp <= 5:
            base += 8.0
        return float(min(budget, base))

    base = 42.0
    if highest_prev >= 120:
        base = 28.0
    elif highest_prev >= 70:
        base = 36.0
    elif avg_prev > 0:
        base = max(34.0, min(48.0, avg_prev * 0.72))

    if needy_count >= 2:
        base += 10.0
    elif needy_count == 1:
        base += 5.0

    if rich_aggressive >= 2:
        base -= 8.0

    if no_water_days == 1:
        base += 18.0
    if hp <= 5:
        base += 10.0
    if day >= 8:
        base += 6.0

    if base < 8.0:
        base = 8.0

    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 50.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 4:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > DAILY_SALARY:
            return min(my_status['budget'], max_prev * 0.95)
        return min(my_status['budget'], max_prev + 5.0)

    return min(my_status['budget'], DAILY_SALARY * 1.1)
